function iniciarCarrosselHistoria() {
  const section = document.querySelector(".our-history-carousel");
  if (!section) return;

  const imagemTopo = section.querySelector("#carrossel-imagem-mapa img");
  const slider = section.querySelector(
    ".slider-historia .jet-listing-grid__slider"
  );

  if (!imagemTopo || !slider) return;

  let botaoProximo = null;
  let botaoAnterior = null;
  let swiperAtual = null;
  let slideSelecionado = null;
  let ultimoAnoCarregado = null;
  let requisicaoImagem = 0;
  let tentativasInicializacao = 0;
  let chegouAoFimFisico = false;
  let observadorSeta = null;

  function getSlides() {
    return Array.from(
      slider.querySelectorAll(".jet-listing-grid__item.swiper-slide")
    ).filter((slide) => !slide.classList.contains("swiper-slide-duplicate"));
  }

  function getAnoFromSlide(slide) {
    const elementoAno =
      slide.querySelector(".bloco-ano[id]") ||
      Array.from(slide.querySelectorAll("[id]")).find((el) =>
        /^\d{4}/.test(el.id)
      );

    return elementoAno?.id.match(/\d{4}/)?.[0] || null;
  }

  function getBases() {
    const bases = [];
    const baseHTML = section.getAttribute("data-image-base");

    if (baseHTML) {
      bases.push(baseHTML.endsWith("/") ? baseHTML : `${baseHTML}/`);
    }

    if (window.HISTORIA_BASE) {
      const baseGlobal = String(window.HISTORIA_BASE);
      bases.push(
        baseGlobal.endsWith("/") ? baseGlobal : `${baseGlobal}/`
      );
    }

    bases.push("/wp-content/uploads/");
    bases.push("/wp-content/uploads/2025/06/");

    return [...new Set(bases)];
  }

  function carregarImagem(urls, indice, onSucesso) {
    if (indice >= urls.length) return;

    const imagem = new Image();

    imagem.onload = () => onSucesso(urls[indice]);
    imagem.onerror = () => carregarImagem(urls, indice + 1, onSucesso);
    imagem.src = urls[indice];
  }

  function atualizarImagemTopo(ano) {
    if (!ano || ano === ultimoAnoCarregado) return;

    const idRequisicao = ++requisicaoImagem;
    const candidatos = getBases().map((base) => `${base}${ano}.svg`);

    carregarImagem(candidatos, 0, (src) => {
      if (idRequisicao !== requisicaoImagem) return;

      imagemTopo.src = src;
      imagemTopo.alt = ano;
      imagemTopo.title = ano;
      ultimoAnoCarregado = ano;
    });
  }

  function atualizarFimFisico() {
    if (!swiperAtual || !botaoProximo) return;

    
    chegouAoFimFisico =
      swiperAtual.isEnd ||
      botaoProximo.classList.contains("swiper-button-disabled");
  }

  function atualizarEstadoSetaProximo() {
    if (!swiperAtual || !botaoProximo || !slideSelecionado) return;

    atualizarFimFisico();

    // Fora do fim, o Swiper controla a seta normalmente.
    if (!chegouAoFimFisico) return;

    const slides = getSlides();
    const indiceSelecionado = slides.indexOf(slideSelecionado);
    const aindaHaAnoParaSelecionar =
      indiceSelecionado >= 0 && indiceSelecionado < slides.length - 1;

    
    botaoProximo.classList.toggle(
      "swiper-button-disabled",
      !aindaHaAnoParaSelecionar
    );

    botaoProximo.setAttribute(
      "aria-disabled",
      aindaHaAnoParaSelecionar ? "false" : "true"
    );

    botaoProximo.tabIndex = aindaHaAnoParaSelecionar ? 0 : -1;
  }

  function selecionarSlide(slide) {
    if (!slide) return;

    slideSelecionado = slide;

    getSlides().forEach((item) => {
      const ativo = item === slide;

      item.classList.toggle("slide-ativo", ativo);

      item
        .querySelector(".bloco-ano")
        ?.classList.toggle("slide-ativo", ativo);
    });

    atualizarImagemTopo(getAnoFromSlide(slide));

    requestAnimationFrame(atualizarEstadoSetaProximo);
  }

  function atualizarSlideAtivoDoSwiper() {
    const slideAtivo = slider.querySelector(
      ".jet-listing-grid__item.swiper-slide-active"
    );

    if (!slideAtivo) return;

    // Ao voltar fisicamente no carrossel, ele sai do modo final.
    atualizarFimFisico();

    selecionarSlide(slideAtivo);
  }

  function adicionarCliquesNosCards() {
    getSlides().forEach((slide) => {
      if (slide.dataset.historyClickBound) return;

      slide.dataset.historyClickBound = "true";

      slide.addEventListener("click", () => {
        selecionarSlide(slide);
      });
    });
  }

  function adicionarNavegacaoFinal() {
    if (!swiperAtual || !botaoProximo || !botaoAnterior) return;

    botaoProximo.addEventListener(
      "click",
      (event) => {
        atualizarFimFisico();

        // Antes do último grupo, deixa o Swiper agir normalmente.
        if (!chegouAoFimFisico) return;

        const slides = getSlides();
        const indiceAtual = slides.indexOf(slideSelecionado);

        // No último grupo: 2023 → 2024 → 2025.
        if (indiceAtual >= 0 && indiceAtual < slides.length - 1) {
          event.preventDefault();
          event.stopImmediatePropagation();

          selecionarSlide(slides[indiceAtual + 1]);
          return;
        }

        // Em 2025 a seta deve permanecer realmente desativada.
        event.preventDefault();
        event.stopImmediatePropagation();
        atualizarEstadoSetaProximo();
      },
      true
    );

    botaoAnterior.addEventListener(
      "click",
      (event) => {
        atualizarFimFisico();

        if (!chegouAoFimFisico) return;

        const slides = getSlides();
        const indiceSelecionado = slides.indexOf(slideSelecionado);

        const slideFisicamenteAtivo = slider.querySelector(
          ".jet-listing-grid__item.swiper-slide-active"
        );
        const indiceFisicamenteAtivo = slides.indexOf(
          slideFisicamenteAtivo
        );

        // No último grupo: 2025 → 2024 → 2023.
        // Em 2023, a próxima seta Voltar usa novamente o Swiper.
        if (indiceSelecionado > indiceFisicamenteAtivo) {
          event.preventDefault();
          event.stopImmediatePropagation();

          selecionarSlide(slides[indiceSelecionado - 1]);
        }
      },
      true
    );
  }

  function observarEstadoDaSeta() {
    if (!botaoProximo || observadorSeta) return;

    observadorSeta = new MutationObserver(() => {
      requestAnimationFrame(atualizarEstadoSetaProximo);
    });

    observadorSeta.observe(botaoProximo, {
      attributes: true,
      attributeFilter: ["class", "aria-disabled", "tabindex"],
    });
  }

  function conectarSwiper() {
    const swiper = slider.swiper;

    // As setas só existem depois de o JetEngine concluir a montagem.
    botaoProximo = section.querySelector(
      ".jet-listing-grid__slider-icon.next-arrow"
    );
    botaoAnterior = section.querySelector(
      ".jet-listing-grid__slider-icon.prev-arrow"
    );

    if (!swiper || !botaoProximo || !botaoAnterior) {
      if (++tentativasInicializacao < 100) {
        setTimeout(conectarSwiper, 100);
      }
      return;
    }

    swiperAtual = swiper;

    atualizarSlideAtivoDoSwiper();
    adicionarCliquesNosCards();
    observarEstadoDaSeta();

    // Nome novo: não colide com scripts antigos, se algum ainda existir.
    if (swiper.historyCarouselStagingV3Conectado) return;
    swiper.historyCarouselStagingV3Conectado = true;

    adicionarNavegacaoFinal();

    swiper.on("slideChange", atualizarSlideAtivoDoSwiper);
    swiper.on("slideChangeTransitionEnd", atualizarSlideAtivoDoSwiper);
    swiper.on("update", atualizarSlideAtivoDoSwiper);
    swiper.on("resize", atualizarSlideAtivoDoSwiper);
  }

  conectarSwiper();
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", iniciarCarrosselHistoria);
} else {
  iniciarCarrosselHistoria();
}